def int_sqrt(n: int) -> int:
    """Return the largest integer r such that r * r <= n.

    pre: n >= 0
    post: __return__ >= 0
    post: __return__ * __return__ <= n
    post: (__return__ + 1) * (__return__ + 1) > n
    """
    if n < 0:
        raise ValueError('n must be non-negative')
    if n < 2:
        return n
    lo, hi = (1, n)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid * mid <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

