def majority(xs: list[int]) -> int | None:
    """Return the value occurring in more than half of the positions of xs, or None.

    pre: isinstance(xs, list)
    post: __return__ is None or xs.count(__return__) * 2 > len(xs)
    post: __return__ is not None or all(xs.count(v) * 2 <= len(xs) for v in xs)
    """
    candidate = None
    count = 0
    for x in xs:
        if count == 0:
            candidate = x
            count = 1
        elif x == candidate:
            count += 1
        else:
            count -= 1
    if candidate is not None and xs.count(candidate) * 2 > len(xs):
        return candidate
    return None

